int kthSmallest(vector<vector<int>>& m, int k) {
    int n = m.size(); long long lo = m[0][0], hi = m[n-1][n-1];
    while (lo < hi) { long long x = lo + (hi - lo) / 2; long long cnt = 0; int j = n - 1;
        for (int i = 0; i < n; i++) { while (j >= 0 && m[i][j] > x) j--; cnt += j + 1; }
        if (cnt >= k) hi = x; else lo = x + 1; }
    return (int)lo;
}
